import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BbQUUm7J.js";const u=JSON.parse('{"title":"Platform API integration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platform-api-integration.md","filePath":"guide/platform-api-integration.md","lastUpdated":1794936786000}'),n={name:"guide/platform-api-integration.md"};function r(s,e,i,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="platform-api-integration" tabindex="-1">Platform API integration <a class="header-anchor" href="#platform-api-integration" aria-label="Permalink to &quot;Platform API integration&quot;">​</a></h1><p>How the CLI relates to the FurlPay hosted platform documented at <a href="https://furlpay.com/docs" target="_blank" rel="noreferrer">furlpay.com/docs</a> — which commands call hosted APIs, which operate locally, which talk to public blockchain RPCs, and the payment-safety rules that hold everywhere. Audited 2026-11-17 against <code>lib/commands.js</code> (the hosted-app surface) and <code>bin/furlpay.js</code> routing.</p><h2 id="the-three-planes" tabindex="-1">The three planes <a class="header-anchor" href="#the-three-planes" aria-label="Permalink to &quot;The three planes&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CLI[&quot;furlpay (bin/furlpay.js)&quot;] --&gt; JS[&quot;JS app surface&lt;br/&gt;(lib/commands.js)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CLI --&gt; TS[&quot;TS execution surface&lt;br/&gt;(dist/cli.js)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CLI --&gt; LOCAL[&quot;Local engines&lt;br/&gt;(finance, escrow, quant)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    JS --&gt;|HTTPS + session cookie| HOSTED[&quot;Hosted platform API&lt;br/&gt;(furlpay.com /api/*)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TS --&gt;|HTTPS| VENUES[&quot;Venues &amp; chains&lt;br/&gt;(Hyperliquid /info, Horizon,&lt;br/&gt;Solana RPC, public oracles)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LOCAL --&gt; DISK[&quot;~/.furlpay/&lt;br/&gt;keystore · ledgers · config&quot;]</span></span></code></pre></div><ol><li><strong>Hosted platform APIs</strong> — session-authenticated app commands (payments, cards, travel, investing, earn) in <code>lib/commands.js</code>. Authenticated by the device-login/OTP session cookie. These correspond to the platform docs (API Routes, Merchant Payments, Payroll, Travels, and so on).</li><li><strong>Public chains &amp; venues</strong> — <code>tx verify</code> (Horizon), <code>faucet</code> (Friendbot), <code>hyperliquid</code>/<code>market</code> (/info), <code>solana</code> (JSON-RPC), <code>oracle</code> (public price sources), Jupiter quotes. No FurlPay backend involved.</li><li><strong>Local-only engines</strong> — <code>finance</code>, <code>escrow</code>, <code>microstructure</code>, <code>algo</code>, <code>fork</code>: state machines and arithmetic over files in <code>~/.furlpay/</code>. No network at all.</li></ol><p>A credential for one plane does nothing on another: <strong>an API credential does not turn on an unconfigured rail</strong>, and a local ledger entry is not a chain fact.</p><h2 id="hosted-endpoints-the-cli-calls" tabindex="-1">Hosted endpoints the CLI calls <a class="header-anchor" href="#hosted-endpoints-the-cli-calls" aria-label="Permalink to &quot;Hosted endpoints the CLI calls&quot;">​</a></h2><p>Verified by reading <code>lib/commands.js</code>:</p><table tabindex="0"><thead><tr><th>Area</th><th>Endpoints</th><th>CLI commands</th></tr></thead><tbody><tr><td>Auth</td><td><code>/api/auth/otp/start</code>, <code>/api/auth/otp/check</code> (+ RFC 8628 device flow)</td><td><code>login</code>, <code>logout</code>, <code>whoami</code></td></tr><tr><td>Wallets</td><td><code>/api/wallets</code>, <code>/api/wallets/transfer</code></td><td><code>balance</code>, <code>send</code></td></tr><tr><td>Payments</td><td><code>/api/v1/payments</code>, <code>/api/payments/*</code></td><td><code>pay</code>, <code>payments</code></td></tr><tr><td>Swaps</td><td><code>/api/swaps</code></td><td><code>swap</code></td></tr><tr><td>Cards</td><td><code>/api/cards</code>, <code>/api/cards/settings</code></td><td><code>card</code>, <code>cards</code></td></tr><tr><td>Investing</td><td><code>/api/investing/portfolio</code>, <code>/api/investing/order</code>, <code>/api/investing/schedule</code></td><td><code>invest</code></td></tr><tr><td>Travel</td><td><code>/api/travel/search</code>, <code>/api/travel/book</code>, <code>/api/travel/trips</code>, <code>/api/travel/cancel/*</code></td><td><code>travel</code></td></tr><tr><td>Earn</td><td><code>/api/earn</code>, <code>/api/earn/vaults</code></td><td><code>earn</code> (JS surface)</td></tr><tr><td>Markets</td><td><code>/api/markets</code>, <code>/api/markets/indices</code>, <code>/api/markets/movers</code></td><td><code>dashboard</code></td></tr><tr><td>On-ramp</td><td><code>/api/onramp/quote</code>, <code>/api/onramp/session</code></td><td>(JS surface)</td></tr><tr><td>Approvals</td><td><code>/api/control-plane/approvals</code></td><td><code>approvals</code></td></tr><tr><td>Health</td><td><code>/api/health</code></td><td><code>status</code>, <code>doctor</code></td></tr></tbody></table><p>Rail availability: the CLI checks <code>/api/rails</code> semantics exactly as the <a href="https://furlpay.com/docs/getting-started/quickstart" target="_blank" rel="noreferrer">platform quickstart</a> prescribes — <strong>check before integrating, re-check before submitting, and treat stale or unavailable status as unknown</strong>.</p><h2 id="payment-safety-contract-identical-to-the-platform-docs" tabindex="-1">Payment-safety contract (identical to the platform docs) <a class="header-anchor" href="#payment-safety-contract-identical-to-the-platform-docs" aria-label="Permalink to &quot;Payment-safety contract (identical to the platform docs)&quot;">​</a></h2><p>These are the load-bearing rules; the CLI enforces the ones it can and labels the rest:</p><ul><li><strong>A fee estimate is not a payment.</strong> <code>/api/payments/fees/estimate</code> (or any quote) prices; nothing settles.</li><li><strong>A payment intent is not a settled transaction.</strong> <code>POST /api/payments/create</code> returning EIP-712 signing data means the wallet can now <em>authorize</em> — not that anything moved.</li><li><strong>An HTTP 200 is not proof of settlement.</strong> Poll the payment status and verify the returned transaction reference (<code>furlpay tx verify &lt;hash&gt;</code> does exactly that for Stellar hashes — honest lookup semantics, <code>404</code> is explicitly <em>not</em> &quot;does not exist&quot;).</li><li><strong>Idempotency.</strong> Use <code>Idempotency-Key</code> on supported routes; the finance layer records an idempotency key per ledger transaction, and replayed intents are refused rather than double-counted.</li><li><strong>Webhooks.</strong> Verify signatures over the raw body, constant-time compare, reject stale timestamps — the same rule the CLI&#39;s own webhook receiver (<code>FURLPAY_FINANCE_WEBHOOK_URL</code>) documents.</li><li><strong>Never treat sandbox, demo inventory, or generated signing data as a production payment.</strong> Every simulated surface in this CLI is labeled at runtime — see the <a href="/furlpay-cli/reference/honesty-matrix">Honesty Matrix</a>.</li></ul><h2 id="authentication-credentials" tabindex="-1">Authentication &amp; credentials <a class="header-anchor" href="#authentication-credentials" aria-label="Permalink to &quot;Authentication &amp; credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plane</th><th>Credential</th><th>Where it lives</th></tr></thead><tbody><tr><td>Hosted API</td><td>Session cookie from device login / OTP</td><td>OS-bound local storage, cookie only attaches to furlpay.com over TLS or loopback (<code>--api-base</code> to any other target goes credential-less, loudly)</td></tr><tr><td>Hyperliquid / Binance</td><td>Private key / API keys</td><td>Environment only (see <a href="/furlpay-cli/guide/environment-variables">Environment variables</a>)</td></tr><tr><td>Stellar</td><td>Encrypted keystore or hardware</td><td><code>~/.furlpay</code> keystore (PBKDF2 + AES-256-GCM) or Ledger</td></tr><tr><td>MCP execution</td><td>Agent policy file</td><td><code>~/.furlpay/agent-policies/</code> — created by <code>wallet agent-keygen</code></td></tr></tbody></table><p>Secrets are never accepted on argv, never logged, and never returned by any command or MCP tool (a property test pins redaction).</p><h2 id="where-the-cli-does-not-integrate-yet" tabindex="-1">Where the CLI does NOT integrate (yet) <a class="header-anchor" href="#where-the-cli-does-not-integrate-yet" aria-label="Permalink to &quot;Where the CLI does NOT integrate (yet)&quot;">​</a></h2><p>Marked unavailable rather than invented — per the platform docs these exist server-side, but no CLI command calls them today:</p><ul><li>Merchant checkout creation/webhooks (<code>/api/merchant/*</code>) — CLI: <strong>not implemented</strong> (use the platform dashboard or the HTTP API directly).</li><li>CCTP cross-chain transfer initiation — CLI: <strong>not implemented</strong> (quotes and balances only).</li><li>LI.FI swap routing — CLI: <strong>not implemented</strong> (<code>swap</code> uses the hosted platform swap endpoint only).</li><li>Settlement workspace operations — CLI: <strong>not implemented</strong>.</li></ul><p>If a future build adds them, they will appear here with the command that calls them and the honesty-matrix row that labels them.</p>`,20)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
